package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
	"unicode"
)

func SolveProblem(s string) string {
	lowerCount := 0
	higherCount := 0
	runes := []rune(s)
	for i := 0; i < len(runes); i++ {
		if unicode.IsLower(runes[i]) {
			lowerCount++
		} else {
			higherCount++
		}

		if lowerCount > len(runes)/2 {
			return strings.ToLower(s)
		}
	}
	if lowerCount == higherCount {
		return strings.ToLower(s)
	}
	return strings.ToUpper(s)
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	s, _ := reader.ReadString('\n')
	s = strings.TrimRight(s, "\r\n")
	fmt.Println(SolveProblem(s))
	reader.ReadString('\n')
}
